SELECT id, order_id, account_id, stock_code, price, quantity, create_time
FROM sold_orders

    account_id = #{accountId}

        AND stock_code = #{stockCode}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM sold_orders

    account_id = #{accountId}

        AND stock_code = #{stockCode}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}

SELECT id, order_key, account_id, stock_code, price, freeze_price, quantity, sold_quantity, type, status, create_time
FROM orders

    account_id = #{accountId}

        AND stock_code = #{code}


        AND status = #{status}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM orders

    account_id = #{accountId}

        AND stock_code = #{code}


        AND status = #{status}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}
